// NOVEL — not generated by CLI Printing Press. See
// .printing-press-patches/garmin-sql-escape-hatch.json.
//
// This file exists to make one re-render hazard loud. tools.go is generated:
// a dogfood run restores validateReadOnlyQuery, stripLeadingSQLNoise and
// hasTrailingSQLStatement inline, and the CLI's `sql` verb keeps working while
// the two surfaces quietly stop sharing a gate. That divergence compiles, so
// only a test catches it.

package mcp

import (
	"context"
	"strings"
	"testing"

	mcplib "github.com/mark3labs/mcp-go/mcp"
	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/sqlguard"
)

// TestMCPSQLGuardIsTheSharedGuard asserts the MCP tool refuses with exactly
// the words internal/sqlguard produces — the same words the `garmin-pp-cli
// sql` verb shows, because it calls sqlguard.Validate directly.
func TestMCPSQLGuardIsTheSharedGuard(t *testing.T) {
	for _, query := range []string{
		`SELECT 1; DROP TABLE resources`,
		"-- harmless\nDROP TABLE resources",
		`ATTACH DATABASE '/tmp/side.db' AS side`,
		`VACUUM INTO '/tmp/copy.db'`,
		`PRAGMA journal_mode=DELETE`,
	} {
		want := sqlguard.Validate(query)
		if want == nil {
			t.Fatalf("sqlguard accepted %q; the guard itself regressed", query)
		}
		if got := validateReadOnlyQuery(query); got == nil || got.Error() != want.Error() {
			t.Fatalf("validateReadOnlyQuery(%q) = %v, want the shared guard's %q — tools.go is no longer delegating to internal/sqlguard", query, got, want)
		}

		result, err := handleSQL(context.Background(), mcplib.CallToolRequest{Params: mcplib.CallToolParams{
			Arguments: map[string]any{"query": query},
		}})
		if err != nil {
			t.Fatalf("handleSQL(%q) returned a transport error: %v", query, err)
		}
		if !result.IsError {
			t.Fatalf("handleSQL accepted %q", query)
		}
		if !strings.Contains(toolResultText(t, result), want.Error()) {
			t.Fatalf("handleSQL(%q) refused with %q, want the shared guard's %q", query, toolResultText(t, result), want.Error())
		}
	}
}

func toolResultText(t *testing.T, result *mcplib.CallToolResult) string {
	t.Helper()
	var b strings.Builder
	for _, content := range result.Content {
		if text, ok := content.(mcplib.TextContent); ok {
			b.WriteString(text.Text)
		}
	}
	return b.String()
}
